partial class ThebestRGB {
 TcpListener mobileListener;CancellationTokenSource mobileStop;string mobileAddress="";
 void StartMobileRemote(){
  try{
   EnsureMobileFirewallRule();
   IPAddress address=Dns.GetHostEntry(Dns.GetHostName()).AddressList.FirstOrDefault(a=>a.AddressFamily==AddressFamily.InterNetwork&&!IPAddress.IsLoopback(a));string ip=address==null?null:address.ToString();
   if(string.IsNullOrEmpty(ip))return;
   mobileAddress="http://"+ip+":18765/";mobileListener=new TcpListener(IPAddress.Any,18765);mobileListener.Start();mobileStop=new CancellationTokenSource();Task.Run(()=>MobileLoop(mobileStop.Token));
  }catch{mobileAddress="";}
 }
 void EnsureMobileFirewallRule(){try{using(var command=Process.Start(new ProcessStartInfo("netsh","advfirewall firewall add rule name=\"ThebestRGB controle pelo celular\" dir=in action=allow protocol=TCP localport=18765 profile=any remoteip=localsubnet"){UseShellExecute=false,CreateNoWindow=true})){command.WaitForExit(3000);}}catch{}}
 string MobileAddresses(){return string.Join("\r\n",NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==OperationalStatus.Up).SelectMany(n=>n.GetIPProperties().UnicastAddresses).Where(a=>a.Address.AddressFamily==AddressFamily.InterNetwork&&!IPAddress.IsLoopback(a.Address)).Select(a=>"http://"+a.Address+":18765/").Distinct().ToArray());}
 async Task MobileLoop(CancellationToken token){try{while(!token.IsCancellationRequested){TcpClient client;try{client=await mobileListener.AcceptTcpClientAsync();}catch{break;}Task.Run(()=>MobileRequest(client));}}catch{}}
 static string MobileValue(string query,string key){foreach(string item in query.TrimStart('?').Split('&')){int p=item.IndexOf('=');if(p>0&&Uri.UnescapeDataString(item.Substring(0,p))==key)return Uri.UnescapeDataString(item.Substring(p+1));}return "";}
 string MobileState(){string result="{}";try{Invoke(new Action(delegate{result=new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{color="#"+global.R.ToString("X2")+global.G.ToString("X2")+global.B.ToString("X2"),brightness=master.Value,mode=effectMode.SelectedIndex,devices=cards.Select((card,index)=>new{index=index,name=card.State.Name,enabled=card.State.Included,brightness=card.State.Brightness}).ToArray(),profiles=profiles.Select((profile,index)=>new{index=index,name=profile.Name}).ToArray()});}));}catch{}return result;}
 void MobileRequest(TcpClient client){using(client)try{NetworkStream stream=client.GetStream();var reader=new StreamReader(stream,Encoding.ASCII);string first=reader.ReadLine();if(string.IsNullOrEmpty(first))return;string[] parts=first.Split(' ');string resource=parts.Length>1?parts[1]:"/";string line;while(!string.IsNullOrEmpty(line=reader.ReadLine())){}Uri uri=new Uri("http://local"+resource);string path=uri.AbsolutePath.ToLowerInvariant();if(path=="/action"){string action=MobileValue(uri.Query,"name");BeginInvoke(new Action(async delegate{if(action=="verify"&&!busy)await VerifyDevices();else if(action=="undo"&&!busy)UndoSetup();else if(action=="auto"&&!busy)testSelected.PerformClick();}));WriteMobile(stream,"ok");return;}if(path=="/state"){WriteMobile(stream,MobileState(),200,"application/json; charset=utf-8");return;}if(path=="/profile"){int index;int.TryParse(MobileValue(uri.Query,"index"),out index);BeginInvoke(new Action(async delegate{if(busy||index<0||index>=profiles.Count)return;profileList.SelectedIndex=index;await LoadProfileAsync();await ApplyCards(cards.Where(card=>card.State.Included).ToList());}));WriteMobile(stream,"ok");return;}if(path=="/stop"){BeginInvoke(new Action(async delegate{if(!busy)await StopEffect();}));WriteMobile(stream,"ok");return;}if(path=="/set"){string hex=MobileValue(uri.Query,"color").Trim().TrimStart('#');int value,mode,brightness;int.TryParse(MobileValue(uri.Query,"mode"),out mode);int.TryParse(MobileValue(uri.Query,"brightness"),out brightness);string[] selected=MobileValue(uri.Query,"devices").Split(new[]{','},StringSplitOptions.RemoveEmptyEntries);if(hex.Length==6&&int.TryParse(hex,System.Globalization.NumberStyles.HexNumber,null,out value)){Color c=Color.FromArgb((value>>16)&255,(value>>8)&255,value&255);BeginInvoke(new Action(async delegate{if(busy)return;if(selected.Length>0)for(int i=0;i<cards.Count;i++)cards[i].State.Included=selected.Contains(i.ToString());if(brightness>=0&&brightness<=100)foreach(var card in cards.Where(card=>card.State.Included)){card.State.Brightness=brightness;card.RefreshState(false);}SetGlobal(c);if(mode>=0&&mode<EffectLibrary.Names.Length)effectMode.SelectedIndex=mode;await ApplyCards(cards.Where(card=>card.State.Included).ToList());}));WriteMobile(stream,"ok");}else WriteMobile(stream,"Cor inválida",400);return;}WriteMobile(stream,MobilePage(),200,"text/html; charset=utf-8");}catch{}}
 static void WriteMobile(NetworkStream stream,string body,int status=200,string type="text/plain; charset=utf-8"){if(type.StartsWith("text/html"))body+=@"<script>(function(){var st=document.createElement('style');st.textContent='.brand{text-align:center}.visual-tools{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:16px 0 8px}.visual-tools button{height:36px;background:#ffffff0d;color:#fff;border:1px solid #ffffff28;border-radius:8px;font-size:11px;transition:.18s}.visual-tools button.active{background:#7046da;border-color:#b89cff}.auto-tool{display:flex;align-items:center;justify-content:space-between;padding:0 11px}.auto-switch{appearance:none;width:36px;height:20px;border-radius:12px;background:#555;position:relative;transition:.18s}.auto-switch:after{content:\'\';position:absolute;width:14px;height:14px;left:3px;top:3px;border-radius:50%;background:#fff;transition:.18s}.auto-switch:checked{background:#8055f0}.auto-switch:checked:after{transform:translateX(16px)}.visual{padding:10px;border:1px solid #a77dff;border-radius:13px;background:#10111b}.visual-title{color:#c5adff;font-size:11px;margin-bottom:8px}.visual-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px}.rig-card{min-height:105px;border:2px solid #a77dff;border-radius:4px;padding:7px;color:#fff;font-size:10px;font-weight:bold}.rig-card svg{width:100%;height:75px;display:block;margin-top:4px}';document.head.appendChild(st);var root=document.querySelector('main'),brand=document.querySelector('.brand'),wrap=document.createElement('section');wrap.innerHTML='<div class=visual-tools><button onclick=&quot;fetch(&#39;/action?name=verify&#39;)&quot;>Verificar dispositivos</button><button onclick=&quot;document.getElementById(&#39;mode&#39;).focus()&quot;>Predefinições</button><button onclick=&quot;fetch(&#39;/action?name=undo&#39;)&quot;>Desfazer</button><label class=auto-tool>Aplicação automática<input id=autoSwitch class=auto-switch type=checkbox></label></div><div class=visual><div class=visual-title>EDITOR VISUAL DO SETUP</div><div class=visual-grid><div class=rig-card>Teclado<svg viewBox=\'0 0 180 70\'><rect x=\'8\' y=\'4\' width=\'164\' height=\'60\' fill=\'none\' stroke=\'#667088\' stroke-width=\'2\'/><path stroke=\'#f2f2f5\' stroke-width=\'9\' stroke-dasharray=\'10 4\' d=\'M18 17h145M18 31h145M18 45h145M18 57h125\'/></svg></div><div class=rig-card>Gabinete<svg viewBox=\'0 0 180 70\'><rect x=\'48\' y=\'3\' width=\'85\' height=\'64\' fill=\'none\' stroke=\'#667088\' stroke-width=\'2\'/><circle cx=\'75\' cy=\'20\' r=\'11\' fill=\'none\' stroke=\'#e6e6eb\' stroke-width=\'5\'/><circle cx=\'75\' cy=\'44\' r=\'11\' fill=\'none\' stroke=\'#e6e6eb\' stroke-width=\'5\'/><circle cx=\'108\' cy=\'37\' r=\'17\' fill=\'none\' stroke=\'#e6e6eb\' stroke-width=\'5\'/><path stroke=\'#e6e6eb\' stroke-width=\'5\' d=\'M97 12h30\'/></svg></div><div class=rig-card>Placa de vídeo<svg viewBox=\'0 0 180 70\'><rect x=\'10\' y=\'10\' width=\'150\' height=\'48\' fill=\'none\' stroke=\'#667088\' stroke-width=\'2\'/><circle cx=\'42\' cy=\'34\' r=\'15\' fill=\'none\' stroke=\'#788197\' stroke-width=\'2\'/><circle cx=\'85\' cy=\'34\' r=\'15\' fill=\'none\' stroke=\'#788197\' stroke-width=\'2\'/><circle cx=\'128\' cy=\'34\' r=\'15\' fill=\'none\' stroke=\'#788197\' stroke-width=\'2\'/><path stroke=\'#e6e6eb\' stroke-width=\'3\' d=\'M25 4h130\'/></svg></div><div class=rig-card>Memórias<svg viewBox=\'0 0 180 70\'><rect x=\'18\' y=\'7\' width=\'145\' height=\'20\' fill=\'none\' stroke=\'#778096\' stroke-width=\'2\'/><rect x=\'18\' y=\'40\' width=\'145\' height=\'20\' fill=\'none\' stroke=\'#778096\' stroke-width=\'2\'/><text x=\'32\' y=\'21\' fill=\'white\' font-size=\'10\'>VIPER</text><text x=\'32\' y=\'54\' fill=\'white\' font-size=\'10\'>VIPER</text></svg></div></div></div>';root.insertBefore(wrap,brand.nextSibling);var bs=wrap.querySelectorAll('.visual-tools button');function selectTool(b){for(var i=0;i<bs.length;i++)bs[i].classList.remove('active');b.classList.add('active')}bs[0].onclick=function(){selectTool(this);fetch('/action?name=verify')};bs[1].onclick=function(){selectTool(this);var m=document.getElementById('mode');m.scrollIntoView({behavior:'smooth',block:'center'});m.focus();m.click()};bs[2].onclick=function(){selectTool(this);fetch('/action?name=undo')};var autos=document.getElementById('autoSwitch');autos.onchange=function(){fetch('/action?name=auto')}})()</script>";byte[] bytes=Encoding.UTF8.GetBytes(body);string headers="HTTP/1.1 "+status+" OK\r\nContent-Type: "+type+"\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\n\r\n";byte[] head=Encoding.ASCII.GetBytes(headers);stream.Write(head,0,head.Length);stream.Write(bytes,0,bytes.Length);}
 string MobilePage(){return @"<!doctype html><meta name='viewport' content='width=device-width,initial-scale=1'><style>html{background:#0d0f18}body{margin:0;min-height:100vh;padding:24px;background:radial-gradient(circle at 15% 0,#49368a 0,transparent 35%),linear-gradient(145deg,#0d0f18,#171224 58%,#0c1220) fixed no-repeat;background-size:cover;color:#fff;font:15px Segoe UI}main{max-width:430px;margin:auto}.brand{color:#c5b7ff;font-size:12px;font-weight:bold;letter-spacing:1px}.brand b{display:block;color:#fff;font-size:26px;margin-top:5px}.card{background:#1a1c2acc;border:1px solid #ffffff14;border-radius:20px;padding:17px;margin-top:16px}.cap{color:#aaa6bd;font-size:11px;font-weight:bold;letter-spacing:1px}.field{width:100%;height:47px;margin-top:9px;box-sizing:border-box;padding:10px;border:1px solid #ffffff18;border-radius:12px;background:#10121c;color:#fff;font:inherit}.colors,.devices{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:12px}.colors button{height:48px;border:0;border-radius:12px;font-weight:bold}.devices{grid-template-columns:repeat(2,1fr)}.device{padding:12px;text-align:left;color:#fff;border:1px solid #ffffff16;border-radius:12px;background:#10121c}.device.on{background:#30234d;border-color:#a184ff}.device small{display:block;color:#aaa6bd;margin-top:3px}.apply{width:100%;height:52px;margin-top:15px;border:0;border-radius:14px;background:linear-gradient(105deg,#b192ff,#7654e8);color:#171122;font-weight:900}.secondary{width:100%;height:42px;margin-top:9px;background:#ffffff12;border:1px solid #ffffff20;border-radius:12px;color:#fff}.status,.note{color:#aaa6bd;margin-top:14px}.dot{display:inline-block;width:8px;height:8px;border-radius:9px;background:#49d796;margin-right:8px}</style><main><div class='brand'>THEBESTRGB<b>Controle do setup</b></div><section class='card'><div class='cap'>COR E EFEITO</div><div class='colors'><button onclick='quick(&quot;ffffff&quot;)'>Branco</button><button style='background:#e84657' onclick='quick(&quot;ff304b&quot;)'>Vermelho</button><button style='background:#3f9df5' onclick='quick(&quot;4bb8ff&quot;)'>Azul</button><button style='background:#28ba7d' onclick='quick(&quot;20e497&quot;)'>Verde</button><button style='background:#8758e9' onclick='quick(&quot;a060ff&quot;)'>Roxo</button><button style='background:#ee9838' onclick='quick(&quot;ff9b38&quot;)'>Laranja</button></div><input id='color' class='field'><input id='brightness' class='field' type='range' min='0' max='100'><select id='mode' class='field'><option value='0'>Cor fixa</option><option value='1'>Arco-íris</option><option value='2'>Respiração</option><option value='3'>Arco-íris suave</option><option value='4'>Onda pelo setup</option><option value='5'>Passagem de luz</option><option value='6'>Aurora</option><option value='7'>Oceano</option><option value='8'>Fogo</option><option value='9'>Pôr do sol</option><option value='10'>Neon</option><option value='11'>Pastel</option><option value='12'>Batimento</option><option value='13'>Vela</option><option value='14'>Respiração alternada</option><option value='15'>Duas cores</option><option value='16'>Elétrica</option><option value='17'>Áudio</option><option value='18'>Ambilight</option></select></section><section class='card'><div class='cap'>DISPOSITIVOS</div><div id='devices' class='devices'></div><button class='apply' onclick='apply()'>Aplicar selecionados</button><button class='secondary' onclick='fetch(&quot;/stop&quot;)'>Parar efeito</button><div id='note' class='note'></div></section><section class='card'><div class='cap'>PERFIS SALVOS</div><div id='profiles'></div></section><div class='status'><i class='dot'></i>Conectado ao ThebestRGB neste PC</div></main><script>let state;async function load(){state=await fetch('/state').then(x=>x.json());color.value=state.color;brightness.value=state.brightness;mode.value=state.mode;draw()}function draw(){devices.innerHTML=state.devices.map(d=>`<button class='device ${d.enabled?'on':''}' onclick='state.devices[${d.index}].enabled=!state.devices[${d.index}].enabled;draw()'><b>${d.enabled?'✓':'○'} ${d.name}</b><small>Brilho ${d.brightness}%</small></button>`).join('');profiles.innerHTML=state.profiles.map(p=>`<button class='secondary' onclick='profile(${p.index})'>${p.name}</button>`).join('')||'<div class=note>Nenhum perfil salvo.</div>'}function quick(c){color.value='#'+c;apply()}function apply(){note.textContent='Aplicando…';let d=state.devices.filter(x=>x.enabled).map(x=>x.index).join(',');fetch('/set?color='+encodeURIComponent(color.value)+'&mode='+mode.value+'&brightness='+brightness.value+'&devices='+d).then(()=>note.textContent='Comando enviado.')}function profile(i){fetch('/profile?index='+i).then(()=>{note.textContent='Perfil aplicado.';setTimeout(load,400)})}load()</script>";}
 void ShowMobileRemote(){if(string.IsNullOrEmpty(mobileAddress)){MessageBox.Show(this,"Não foi possível iniciar o controle pelo celular nesta rede.","ThebestRGB");return;}using(var dialog=new Form{Text="ThebestRGB / Controle pelo celular",ClientSize=new Size(510,218),BackColor=surface,ForeColor=Color.White,Font=new Font("Segoe UI",10),StartPosition=FormStartPosition.CenterParent,MaximizeBox=false,MinimizeBox=false}){dialog.Controls.Add(new Label{Text="No celular, conectado ao mesmo Wi-Fi, abra:",AutoSize=true,Location=new Point(24,34)});var address=new TextBox{ReadOnly=true,Multiline=true,Text=mobileAddress,BackColor=Color.FromArgb(35,38,50),ForeColor=Color.White,BorderStyle=BorderStyle.FixedSingle};address.SetBounds(24,65,462,50);dialog.Controls.Add(address);dialog.Controls.Add(new Label{Text="Funciona somente nesta rede. Mantenha o ThebestRGB aberto neste PC.",ForeColor=Muted,Size=new Size(462,28),Location=new Point(26,128)});var close=Button("Fechar",surface);close.DialogResult=DialogResult.OK;close.SetBounds(356,170,130,32);dialog.Controls.Add(close);dialog.AcceptButton=close;DarkDialogChrome.Attach(dialog,dialog.Text);dialog.ShowDialog(this);}}
